-- This intentionally creates session definitions only: no programme version or Plan Package.

-- Broad Jump is an established canonical identity. The disposable baseline predates it.
DO $$
DECLARE v_existing integer; v_exact integer;
BEGIN
 SELECT count(*) INTO v_existing FROM public.exercises_v2 WHERE exercise_id='EX-024';
 SELECT count(*) INTO v_exact FROM public.exercises_v2 WHERE (exercise_id,name,slug,published) IN (('EX-024','Broad Jump','broad-jump',true));
 IF v_existing = 1 AND v_exact = 1 THEN RETURN; END IF;
 IF v_existing <> 0 THEN RAISE EXCEPTION 'Apollo Week 12 canonical reuse conflict: EX-024 must be absent or byte-for-byte expected'; END IF;
 INSERT INTO public.exercises_v2 (exercise_id,name,slug,published,category,movement_pattern,equipment,primary_capability,purpose) VALUES ('EX-024','Broad Jump','broad-jump',true,'Plyometric','Jump','Bodyweight','Power','Existing canonical identity required by Apollo Week 12 broad-jump assessment.');
END $$;

-- Minimal canonical identity required by the authored max-strict-pull-up assessment.
DO $$
DECLARE v_existing integer; v_exact integer;
