 SELECT count(*) INTO v_exact FROM public.exercises_v2 WHERE (exercise_id,name,slug,published) IN (('EX-149','Strict Pull-Up','strict-pull-up',true));
 IF v_existing = 1 AND v_exact = 1 THEN RETURN; END IF;
 IF v_existing <> 0 THEN RAISE EXCEPTION 'Apollo Week 12 canonical exercise conflict: EX-149 must be absent or byte-for-byte expected'; END IF;
 INSERT INTO public.exercises_v2 (exercise_id,name,slug,published,category,movement_pattern,equipment,primary_capability,purpose) VALUES ('EX-149','Strict Pull-Up','strict-pull-up',true,'Pull','Vertical Pull','Pull-up Bar','Strength','Canonical identity required by Apollo Week 12 max strict pull-up assessment; distinct from weighted and neutral-grip pull-ups.');
END $$;

